package com.example.snake3d;

import android.content.Context; import android.opengl.GLES20; import android.opengl.GLSurfaceView; import android.opengl.Matrix; import android.widget.TextView; import java.nio.*; import java.util.*; import javax.microedition.khronos.egl.EGLConfig; import javax.microedition.khronos.opengles.GL10;

public class SnakeRenderer implements GLSurfaceView.Renderer {
  private final Context context; private int program, aPos, aNorm, uMvp, uModel, uColor, uLight; private FloatBuffer sphereV, sphereN; private ShortBuffer sphereI; private int sphereCount; private float[] proj=new float[16], view=new float[16], vp=new float[16], model=new float[16], mvp=new float[16];
  private final ArrayList<int[]> body=new ArrayList<>(); private int dir=3, score=0; private int[] food={8,7}; private long last=0; private boolean dead=false; private TextView scoreView;
  public SnakeRenderer(Context c){context=c; reset();} public void setScoreView(TextView t){scoreView=t;} public void turn(int d){if((d+2)%4!=dir)dir=d;} public void restart(){reset();} private void reset(){body.clear();body.add(new int[]{4,7});body.add(new int[]{3,7});body.add(new int[]{2,7});dir=3;score=0;dead=false;food=new int[]{8,7};}
  @Override public void onSurfaceCreated(GL10 gl,EGLConfig cfg){GLES20.glClearColor(.035f,.055f,.085f,1);GLES20.glEnable(GLES20.GL_DEPTH_TEST); String vs="attribute vec3 aPosition; attribute vec3 aNormal; uniform mat4 uMVP; uniform mat4 uModel; varying vec3 vN; varying vec3 vP; void main(){vN=mat3(uModel)*aNormal; vP=(uModel*vec4(aPosition,1.0)).xyz; gl_Position=uMVP*vec4(aPosition,1.0);}"; String fs="precision mediump float; uniform vec4 uColor; uniform vec3 uLight; varying vec3 vN; varying vec3 vP; void main(){vec3 n=normalize(vN); float d=max(dot(n,normalize(uLight-vP)),0.0); float l=.28+.72*d; gl_FragColor=vec4(uColor.rgb*l,uColor.a);}"; program=GLES20.glCreateProgram(); int v=shader(GLES20.GL_VERTEX_SHADER,vs), f=shader(GLES20.GL_FRAGMENT_SHADER,fs); GLES20.glAttachShader(program,v);GLES20.glAttachShader(program,f);GLES20.glLinkProgram(program); aPos=GLES20.glGetAttribLocation(program,"aPosition");aNorm=GLES20.glGetAttribLocation(program,"aNormal");uMvp=GLES20.glGetUniformLocation(program,"uMVP");uModel=GLES20.glGetUniformLocation(program,"uModel");uColor=GLES20.glGetUniformLocation(program,"uColor");uLight=GLES20.glGetUniformLocation(program,"uLight"); makeSphere(); }
  private int shader(int type,String src){int s=GLES20.glCreateShader(type);GLES20.glShaderSource(s,src);GLES20.glCompileShader(s);return s;}
  private void makeSphere(){int rings=12,sectors=16; ArrayList<Float> vs=new ArrayList<>(),ns=new ArrayList<>(); for(int r=0;r<=rings;r++){double p=Math.PI*r/rings;for(int s=0;s<=sectors;s++){double t=2*Math.PI*s/sectors;float x=(float)(Math.sin(p)*Math.cos(t)),y=(float)Math.cos(p),z=(float)(Math.sin(p)*Math.sin(t));vs.add(x);vs.add(y);vs.add(z);ns.add(x);ns.add(y);ns.add(z);}} ArrayList<Short> ix=new ArrayList<>();for(int r=0;r<rings;r++)for(int s=0;s<sectors;s++){short a=(short)(r*(sectors+1)+s),b=(short)(a+sectors+1);ix.add(a);ix.add(b);ix.add((short)(a+1));ix.add((short)(a+1));ix.add(b);ix.add((short)(b+1));} sphereV=floats(vs);sphereN=floats(ns);ByteBuffer bb=ByteBuffer.allocateDirect(ix.size()*2).order(ByteOrder.nativeOrder());sphereI=bb.asShortBuffer();for(short q:ix)sphereI.put(q);sphereI.position(0);sphereCount=ix.size();}
  private FloatBuffer floats(ArrayList<Float> a){ByteBuffer b=ByteBuffer.allocateDirect(a.size()*4).order(ByteOrder.nativeOrder());FloatBuffer f=b.asFloatBuffer();for(float x:a)f.put(x);f.position(0);return f;}
  @Override public void onSurfaceChanged(GL10 gl,int w,int h){GLES20.glViewport(0,0,w,h);Matrix.perspectiveM(proj,0,48,(float)w/h,.1f,100);}
  @Override public void onDrawFrame(GL10 gl){GLES20.glClear(GLES20.GL_COLOR_BUFFER_BIT|GLES20.GL_DEPTH_BUFFER_BIT);long now=System.currentTimeMillis();if(!dead&&now-last>190){step();last=now;} if(scoreView!=null)scoreView.post(()->scoreView.setText(dead?"GAME OVER   •   SCORE: "+score:"SNAKE 3D   •   SCORE: "+score));
    int[] head=body.get(0); float hx=head[0]-7.5f, hz=head[1]-7.5f; Matrix.setLookAtM(view,0,hx+5,9,hz+8,hx,0,hz,0,1,0);Matrix.multiplyMM(vp,0,proj,0,view,0);GLES20.glUseProgram(program);GLES20.glEnableVertexAttribArray(aPos);GLES20.glEnableVertexAttribArray(aNorm);GLES20.glVertexAttribPointer(aPos,3,GLES20.GL_FLOAT,false,0,sphereV);GLES20.glVertexAttribPointer(aNorm,3,GLES20.GL_FLOAT,false,0,sphereN);GLES20.glUniform3f(uLight,-5,12,8);
    // floor tiles
    for(int x=0;x<16;x++)for(int z=0;z<16;z++){float shade=((x+z)&1)==0?.12f:.16f; draw(x-7.5f,-.48f,z-7.5f,.49f,.035f,.49f,shade,shade+.025f,shade+.04f,1);}
    // food
    draw(food[0]-7.5f,0,food[1]-7.5f,.34f,.34f,.34f,.95f,.16f,.08f,1);
    // body segments
    for(int i=body.size()-1;i>=1;i--){int[] p=body.get(i);float s=.34f;draw(p[0]-7.5f,0,p[1]-7.5f,s,s,s,.08f,.63f,.43f,1);}
    // head: skin-toned realistic-style 3D head, hair cap, nose, eyes, suit collar
    draw(hx,0,hz,.43f,.48f,.43f,.91f,.67f,.48f,1); draw(hx,.30f,hz,.43f,.20f,.44f,.88f,.61f,.12f,1);
    draw(hx,.09f,hz-.39f,.12f,.11f,.10f,.96f,.75f,.58f,1); draw(hx-.17f,.09f,hz-.34f,.055f,.045f,.035f,.12f,.12f,.13f,1); draw(hx+.17f,.09f,hz-.34f,.055f,.045f,.035f,.12f,.12f,.13f,1);
    draw(hx,-.37f,hz,.40f,.25f,.42f,.08f,.12f,.20f,1);
  }
  private void step(){int[] h=body.get(0);int x=h[0],z=h[1];if(dir==0)z--;if(dir==1)x--;if(dir==2)z++;if(dir==3)x++;if(x<0||x>15||z<0||z>15){dead=true;return;}for(int i=0;i<body.size()-1;i++)if(body.get(i)[0]==x&&body.get(i)[1]==z){dead=true;return;}body.add(0,new int[]{x,z});if(x==food[0]&&z==food[1]){score+=10;Random r=new Random();food=new int[]{r.nextInt(16),r.nextInt(16)};}else body.remove(body.size()-1);}
  private void draw(float x,float y,float z,float sx,float sy,float sz,float r,float g,float b,float a){Matrix.setIdentityM(model,0);Matrix.translateM(model,0,x,y,z);Matrix.scaleM(model,0,sx,sy,sz);Matrix.multiplyMM(mvp,0,vp,0,model,0);GLES20.glUniformMatrix4fv(uMvp,1,false,mvp,0);GLES20.glUniformMatrix4fv(uModel,1,false,model,0);GLES20.glUniform4f(uColor,r,g,b,a);GLES20.glDrawElements(GLES20.GL_TRIANGLES,sphereCount,GLES20.GL_UNSIGNED_SHORT,sphereI);}
}
